.status .when { display: block; padding-left: 21px; }"""),
("  .hero-name { font-size: 19vw; padding-top: 12vh; }","  .hero-name { font-size: 24vw; padding-top: 9vh; }"),
("""    document.querySelectorAll('[data-reveal]').forEach(function (el) { io.observe(el); });""",
"""    /* a clipped element never intersects, so the drawings are watched through their article */
    var proxy = new Map();
    document.querySelectorAll('[data-reveal]').forEach(function (el) {
      if (el.classList.contains('case-art')) { proxy.set(el.parentElement, el); io.observe(el.parentElement); }
      else io.observe(el);
    });"""),
("""        if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); }""",
