input.command:
cat > /tmp/mltest/t.mjs <<EOF
const { Browser, sleep } = await import('$PWD/.claude/skills/design-taste-frontend/scripts/lib/cdp.mjs');
const b = await Browser.launch({ width: 390, height: 844 });
const p = await b.newPage();
await p.setViewport({ width: 390, height: 844, mobile: true });
await p.goto('file://$PWD/index.html');
const r = await p.eval(() => {
  const out = {};
  const q = (s) => document.querySelector(s);
  q('#menu-btn').click(); out.menuOpen = q('#nav').classList.contains('open') && getComputedStyle(q('#nav')).display;
  q('#nav a').click(); out.menuClosed = !q('#nav').classList.contains('open');
  const t0 = document.documentElement.dataset.theme; q('#theme').click(); out.theme = t0 + '->' + document.documentElement.dataset.theme + ' pressed=' + q('#theme').getAttribute('aria-pressed');
  q('[data-filter="Field notes"]').click(); out.filter = [...document.querySelectorAll('.post')].filter(x => !x.hidden).length + ' | ' + q('#post-count').textContent;
  q('[data-filter="all"]').click(); out.all = [...document.querySelectorAll('.post')].filter(x => !x.hidden).length;
  q('[data-ver="after"]').click(); out.after = q('#tide-body').textContent.slice(0, 60);
  q('[data-day="mon"]').click(); out.mon = q('#tide-body').textContent.slice(0, 60);
  out.time = q('#local-time').textContent; out.cd = q('#countdown').textContent;
  out.emailFs = getComputedStyle(q('#email')).fontSize; out.overflow = document.documentElement.scrollWidth;
  return out;
});
console.log(r);
await b.close(); process.exit(0);
EOF
node /tmp/mltest/t.mjs

